/* ============================================================
   style.css — Personal Dashboard
   Single CSS file. Persona 5-inspired palette.
   Supports light / dark mode via [data-theme] on <html>.
   ============================================================ */

/* ------------------------------------------------------------
   1. DESIGN TOKENS
   ------------------------------------------------------------ */
:root {
  /* Brand palette */
  --red:   #E61C1C;
  --gold:  #F0C040;
  --black: #0D0D0D;
  --white: #FFFFFF;

  /* Dark theme (default) */
  --bg:           #0D0D0D;
  --bg-surface:   #141414;
  --bg-card:      #1a1a1a;
  --bg-input:     rgba(255, 255, 255, 0.06);
  --border:       rgba(255, 255, 255, 0.1);
  --border-focus: var(--gold);
  --text:         #FFFFFF;
  --text-muted:   rgba(255, 255, 255, 0.55);
  --text-on-btn:  #FFFFFF;
  --accent:       var(--red);
  --accent2:      var(--gold);
  --shadow:       0 4px 24px rgba(0, 0, 0, 0.5);
  --shadow-hover: 0 6px 32px rgba(230, 28, 28, 0.25);

  /* Typography */
  --font-heading: 'Oswald', 'Anton', sans-serif;
  --font-body:    system-ui, -apple-system, 'Segoe UI', sans-serif;

  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 0.75rem;
  --space-md: 1.25rem;
  --space-lg: 2rem;
  --space-xl: 3rem;

  /* Radius */
  --radius-sm: 3px;
  --radius-md: 6px;

  /* Transitions */
  --dur-fast:  180ms;
  --dur-slow:  350ms;
  --ease:      cubic-bezier(0.22, 1, 0.36, 1);
}

/* Light theme overrides */
[data-theme="light"] {
  --bg:           #F5F5F5;
  --bg-surface:   #EBEBEB;
  --bg-card:      #FFFFFF;
  --bg-input:     rgba(0, 0, 0, 0.04);
  --border:       rgba(0, 0, 0, 0.12);
  --text:         #0D0D0D;
  --text-muted:   rgba(0, 0, 0, 0.5);
  --text-on-btn:  #FFFFFF;
  --shadow:       0 4px 24px rgba(0, 0, 0, 0.1);
  --shadow-hover: 0 6px 32px rgba(230, 28, 28, 0.18);
}

/* ------------------------------------------------------------
   2. RESET & BASE
   ------------------------------------------------------------ */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
  transition: background-color var(--dur-slow) var(--ease),
              color            var(--dur-slow) var(--ease);
}

img { display: block; max-width: 100%; }
ul  { list-style: none; }
a   { color: inherit; text-decoration: none; }

button {
  font: inherit;
  cursor: pointer;
  background: none;
  border: none;
}

/* ------------------------------------------------------------
   3. TYPOGRAPHY
   ------------------------------------------------------------ */
h1, h2, h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* ------------------------------------------------------------
   4. HEADER
   ------------------------------------------------------------ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--space-lg);
  height: 3.25rem;
  background-color: var(--bg-surface);
  border-bottom: 2px solid var(--red);
  transition: background-color var(--dur-slow) var(--ease);
}

.site-header__brand {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--red);
}

.site-header__controls {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

/* ------------------------------------------------------------
   5. BUTTONS
   ------------------------------------------------------------ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4em;
  padding: 0.6rem 1.4rem;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  border: 2px solid transparent;
  border-radius: var(--radius-sm);
  transition:
    background-color var(--dur-fast) var(--ease),
    color            var(--dur-fast) var(--ease),
    border-color     var(--dur-fast) var(--ease),
    box-shadow       var(--dur-fast) var(--ease);
  min-height: 44px;
  min-width: 44px;
  white-space: nowrap;
}

.btn--primary {
  background-color: var(--red);
  color: #fff;
  border-color: var(--red);
}
.btn--primary:hover,
.btn--primary:focus-visible {
  background-color: transparent;
  color: var(--red);
}

.btn--outline {
  background-color: transparent;
  color: var(--text);
  border-color: var(--border-focus);
}
.btn--outline:hover,
.btn--outline:focus-visible {
  background-color: var(--gold);
  color: var(--black);
  border-color: var(--gold);
}

.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border-color: var(--border);
}
.btn--ghost:hover,
.btn--ghost:focus-visible {
  background-color: var(--bg-input);
  color: var(--text);
  border-color: var(--text-muted);
}

.btn--sm {
  padding: 0.4rem 0.9rem;
  font-size: 0.8rem;
  min-height: 36px;
}

.btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  font-size: 1.2rem;
  border: 2px solid var(--border);
  transition: border-color var(--dur-fast) var(--ease),
              background-color var(--dur-fast) var(--ease);
}
.btn-icon:hover,
.btn-icon:focus-visible {
  border-color: var(--gold);
  background-color: var(--bg-input);
}

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

/* ------------------------------------------------------------
   6. DASHBOARD GRID
   ------------------------------------------------------------ */
.dashboard {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: var(--space-lg);
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--space-lg);
}

/* ------------------------------------------------------------
   7. CARDS
   ------------------------------------------------------------ */
.card {
  background-color: var(--bg-card);
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  box-shadow: var(--shadow);
  transition:
    background-color var(--dur-slow) var(--ease),
    border-color     var(--dur-fast) var(--ease),
    box-shadow       var(--dur-fast) var(--ease);
  position: relative;
  overflow: hidden;
}

/* Red left accent strip */
.card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: var(--red);
  border-radius: var(--radius-md) 0 0 var(--radius-md);
}

.card:hover {
  border-color: rgba(230, 28, 28, 0.4);
  box-shadow: var(--shadow-hover);
}

.card__title {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold);
}

.card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* Greeting card spans 2 columns on wide screens */
.card--greeting {
  grid-column: 1 / -1;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-md);
  background: linear-gradient(135deg, #1a0000 0%, var(--bg-card) 60%);
}

[data-theme="light"] .card--greeting {
  background: linear-gradient(135deg, #fff0f0 0%, var(--bg-card) 60%);
}

/* ------------------------------------------------------------
   8. GREETING
   ------------------------------------------------------------ */
.greeting__time {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 400;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.greeting__name {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text);
  margin-top: 0.2rem;
}

/* Red "slash" accent before the name */
.greeting__name::before {
  content: '// ';
  color: var(--red);
  font-weight: 700;
}

.greeting__date {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.greeting__clock {
  font-family: var(--font-heading);
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--gold);
  margin-top: 0.15rem;
}

/* ------------------------------------------------------------
   9. FOCUS TIMER
   ------------------------------------------------------------ */
.timer__display {
  font-family: var(--font-heading);
  font-size: clamp(3.5rem, 8vw, 5.5rem);
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--text);
  text-align: center;
  line-height: 1;
}

.timer__colon {
  color: var(--red);
  /* blink handled by JS toggling opacity */
  transition: opacity 0.2s;
}

.timer__controls {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  justify-content: center;
}

.timer__custom {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  margin-top: var(--space-xs);
}

.timer__custom-row {
  display: flex;
  gap: var(--space-sm);
  align-items: center;
}

.timer__custom-row .form__input {
  width: 80px;
  text-align: center;
}

/* Timer running state — pulse the display */
.card--timer.is-running .timer__display {
  color: var(--gold);
}

/* Timer finished state */
.card--timer.is-done .timer__display {
  color: var(--red);
  animation: timerPulse 0.6s ease-in-out 4;
}

@keyframes timerPulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.3; }
}

/* ------------------------------------------------------------
   10. TO-DO LIST
   ------------------------------------------------------------ */
.todo__form {
  display: flex;
  gap: var(--space-sm);
  align-items: center;
}

.todo__form .form__input {
  flex: 1;
}

.todo__list {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  max-height: 360px;
  overflow-y: auto;
  padding-right: 2px;
}

/* Scrollbar styling */
.todo__list::-webkit-scrollbar {
  width: 4px;
}
.todo__list::-webkit-scrollbar-track {
  background: var(--bg-input);
}
.todo__list::-webkit-scrollbar-thumb {
  background: var(--red);
  border-radius: 2px;
}

.todo__item {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  transition: border-color var(--dur-fast) var(--ease),
              background   var(--dur-fast) var(--ease);
  animation: slideIn var(--dur-slow) var(--ease);
}

@keyframes slideIn {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: none; }
}

.todo__item:hover {
  border-color: var(--red);
}

.todo__checkbox {
  width: 18px;
  height: 18px;
  min-width: 18px;
  accent-color: var(--red);
  cursor: pointer;
}

.todo__text {
  flex: 1;
  font-size: 0.95rem;
  word-break: break-word;
  transition: color var(--dur-fast) var(--ease),
              text-decoration var(--dur-fast) var(--ease);
}

.todo__item--done .todo__text {
  text-decoration: line-through;
  color: var(--text-muted);
}

.todo__actions {
  display: flex;
  gap: 4px;
  opacity: 0;
  transition: opacity var(--dur-fast) var(--ease);
}

.todo__item:hover .todo__actions,
.todo__item:focus-within .todo__actions {
  opacity: 1;
}

.todo__btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  border: 1px solid var(--border);
  color: var(--text-muted);
  transition: background-color var(--dur-fast) var(--ease),
              color            var(--dur-fast) var(--ease),
              border-color     var(--dur-fast) var(--ease);
}

.todo__btn:hover {
  background-color: var(--red);
  color: #fff;
  border-color: var(--red);
}

.todo__btn--edit:hover {
  background-color: var(--gold);
  color: var(--black);
  border-color: var(--gold);
}

/* Empty state */
.todo__empty {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: var(--space-lg) 0;
  font-style: italic;
}

/* ------------------------------------------------------------
   11. QUICK LINKS
   ------------------------------------------------------------ */
.links__form {
  display: grid;
  grid-template-columns: 1fr 2fr auto;
  gap: var(--space-sm);
  align-items: center;
}

.links__grid {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.link__item {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  animation: slideIn var(--dur-slow) var(--ease);
}

.link__btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4em;
  padding: 0.45rem 0.9rem;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  background: var(--bg-input);
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  text-decoration: none;
  transition: background-color var(--dur-fast) var(--ease),
              border-color     var(--dur-fast) var(--ease),
              color            var(--dur-fast) var(--ease),
              box-shadow       var(--dur-fast) var(--ease);
  min-height: 36px;
}

.link__btn:hover,
.link__btn:focus-visible {
  background-color: var(--red);
  border-color: var(--red);
  color: #fff;
  box-shadow: 3px 3px 0 var(--gold);
}

.link__delete {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  border: 1px solid var(--border);
  color: var(--text-muted);
  opacity: 0;
  transition: opacity    var(--dur-fast) var(--ease),
              background var(--dur-fast) var(--ease),
              color      var(--dur-fast) var(--ease);
}

.link__item:hover .link__delete,
.link__item:focus-within .link__delete {
  opacity: 1;
}

.link__delete:hover {
  background-color: var(--red);
  color: #fff;
  border-color: var(--red);
}

/* Empty state */
.links__empty {
  color: var(--text-muted);
  font-size: 0.9rem;
  font-style: italic;
}

/* ------------------------------------------------------------
   12. FORM ELEMENTS
   ------------------------------------------------------------ */
.form__label {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold);
}

.form__input {
  width: 100%;
  background: var(--bg-input);
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 0.95rem;
  padding: 0.55rem 0.9rem;
  transition: border-color var(--dur-fast) var(--ease),
              background   var(--dur-fast) var(--ease),
              box-shadow   var(--dur-fast) var(--ease);
}

.form__input:focus {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(240, 192, 64, 0.2);
}

.form__input::placeholder {
  color: var(--text-muted);
}

.form__error {
  font-size: 0.8rem;
  color: var(--red);
  min-height: 1.2em;
  display: block;
}

.form__hint {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.form__group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

/* Remove number input spin buttons */
input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  -webkit-appearance: none;
}
input[type="number"] { -moz-appearance: textfield; }

/* ------------------------------------------------------------
   13. MODALS
   ------------------------------------------------------------ */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-md);
  animation: fadeIn var(--dur-fast) var(--ease);
}

.modal-overlay[hidden] {
  display: none;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.modal {
  background: var(--bg-card);
  border: 2px solid var(--red);
  border-radius: var(--radius-md);
  padding: var(--space-lg);
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  animation: slideUp var(--dur-slow) var(--ease);
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: none; }
}

.modal__title {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gold);
}

.modal__actions {
  display: flex;
  gap: var(--space-sm);
  margin-top: var(--space-xs);
}

/* ------------------------------------------------------------
   14. REDUCED MOTION
   ------------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    transition-duration: 1ms !important;
  }
}

/* ------------------------------------------------------------
   15. RESPONSIVE
   ------------------------------------------------------------ */
@media (max-width: 680px) {
  .dashboard {
    grid-template-columns: 1fr;
    padding: var(--space-md);
    gap: var(--space-md);
  }

  .card--greeting {
    flex-direction: column;
    align-items: flex-start;
  }

  .links__form {
    grid-template-columns: 1fr;
  }

  .timer__controls {
    gap: var(--space-xs);
  }

  .todo__form {
    flex-wrap: wrap;
  }
}

@media (max-width: 420px) {
  .site-header {
    padding: 0 var(--space-md);
  }

  .timer__display {
    font-size: clamp(3rem, 15vw, 4rem);
  }
}

/**
 * app.js — Personal Dashboard
 * Vanilla JavaScript, no frameworks.
 *
 * Features:
 *   - Greeting  : time-based greeting, current date & live clock
 *   - Focus Timer: configurable countdown (default 25 min), start/stop/reset
 *   - To-Do List : add, edit, complete, delete; LocalStorage; duplicate prevention; sort
 *   - Quick Links: add, open, delete; LocalStorage
 *
 * Challenges implemented:
 *   1. Light / Dark mode toggle
 *   2. Custom name in greeting
 *   3. Prevent duplicate tasks
 */

'use strict';

/* ============================================================
   STORAGE HELPERS
   ============================================================ */

const Storage = {
  get(key, fallback = null) {
    try {
      const raw = localStorage.getItem(key);
      return raw !== null ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  },
  set(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // storage quota exceeded — fail silently
    }
  },
};

/* ============================================================
   GREETING MODULE
   Handles: time-based greeting text, live clock, date display,
            custom user name (Challenge 2)
   ============================================================ */

const Greeting = (() => {
  const elTime  = document.getElementById('greeting-time');
  const elName  = document.getElementById('greeting-name');
  const elDate  = document.getElementById('greeting-date');
  const elClock = document.getElementById('greeting-clock');

  // ── name modal elements ──
  const openBtn    = document.getElementById('open-name-modal');
  const overlay    = document.getElementById('name-modal-overlay');
  const nameInput  = document.getElementById('name-input');
  const nameForm   = document.getElementById('name-form');
  const closeBtn   = document.getElementById('close-name-modal');

  let _tickInterval = null;

  /** Return greeting phrase based on current hour. */
  function _getGreetingPhrase(hour) {
    if (hour >= 5  && hour < 12) return 'Good morning';
    if (hour >= 12 && hour < 17) return 'Good afternoon';
    if (hour >= 17 && hour < 21) return 'Good evening';
    return 'Good night';
  }

  /** Format a Date object as e.g. "Wednesday, August 12, 2026". */
  function _formatDate(date) {
    return date.toLocaleDateString('en-US', {
      weekday: 'long',
      year:    'numeric',
      month:   'long',
      day:     'numeric',
    });
  }

  /** Format a Date object as HH:MM:SS (12-hour). */
  function _formatClock(date) {
    return date.toLocaleTimeString('en-US', {
      hour:   '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  }

  /** Update all greeting DOM elements. */
  function _tick() {
    const now  = new Date();
    const hour = now.getHours();

    elTime.textContent  = _getGreetingPhrase(hour);
    elDate.textContent  = _formatDate(now);
    elClock.textContent = _formatClock(now);
  }

  /** Render the name — falls back to "There" if not set. */
  function _renderName() {
    const saved = Storage.get('dashboard_name', '');
    elName.textContent = saved.trim() ? saved.trim() : 'There';
  }

  /** Open the name modal and focus the input. */
  function _openModal() {
    const saved = Storage.get('dashboard_name', '');
    nameInput.value = saved;
    overlay.hidden = false;
    nameInput.focus();
  }

  /** Close the name modal. */
  function _closeModal() {
    overlay.hidden = true;
    openBtn.focus();
  }

  /** Save name and close. */
  function _saveName(e) {
    e.preventDefault();
    const value = nameInput.value.trim();
    Storage.set('dashboard_name', value);
    _renderName();
    _closeModal();
  }

  /** Close modal on overlay background click. */
  function _overlayClick(e) {
    if (e.target === overlay) _closeModal();
  }

  /** Close modal on Escape key. */
  function _overlayKeydown(e) {
    if (e.key === 'Escape') _closeModal();
  }

  function init() {
    _renderName();
    _tick();
    _tickInterval = setInterval(_tick, 1000);

    openBtn.addEventListener('click', _openModal);
    closeBtn.addEventListener('click', _closeModal);
    nameForm.addEventListener('submit', _saveName);
    overlay.addEventListener('click', _overlayClick);
    overlay.addEventListener('keydown', _overlayKeydown);
  }

  return { init };
})();

/* ============================================================
   TIMER MODULE
   Handles: configurable countdown, start/stop/reset, blink colon
   ============================================================ */

const Timer = (() => {
  const card       = document.querySelector('.card--timer');
  const elMinutes  = document.getElementById('timer-minutes');
  const elSeconds  = document.getElementById('timer-seconds');
  const elColon    = document.querySelector('.timer__colon');
  const startBtn   = document.getElementById('timer-start');
  const stopBtn    = document.getElementById('timer-stop');
  const resetBtn   = document.getElementById('timer-reset');
  const durationIn = document.getElementById('timer-duration');
  const setBtn     = document.getElementById('timer-set');

  let _totalSeconds  = 25 * 60;
  let _remaining     = _totalSeconds;
  let _intervalId    = null;
  let _isRunning     = false;
  let _colonVisible  = true;

  /** Format seconds as MM:SS. */
  function _format(secs) {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return {
      m: String(m).padStart(2, '0'),
      s: String(s).padStart(2, '0'),
    };
  }

  /** Update the display. */
  function _render() {
    const { m, s } = _format(_remaining);
    elMinutes.textContent = m;
    elSeconds.textContent = s;
    // Update document title so users can track from other tabs
    document.title = _isRunning ? `${m}:${s} — Dashboard` : 'Dashboard';
  }

  /** Called every second while running. */
  function _tick() {
    // Blink colon
    _colonVisible = !_colonVisible;
    elColon.style.opacity = _colonVisible ? '1' : '0';

    if (_remaining <= 0) {
      _finish();
      return;
    }
    _remaining--;
    _render();
  }

  /** Timer reaches zero. */
  function _finish() {
    _stop();
    card.classList.remove('is-running');
    card.classList.add('is-done');
    elColon.style.opacity = '1';
    document.title = 'Time\'s up! — Dashboard';
    // Simple beep via Web Audio API (no asset file needed)
    _beep();
  }

  /** Play a short beep using Web Audio API. */
  function _beep() {
    try {
      const ctx  = new (window.AudioContext || window.webkitAudioContext)();
      const osc  = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, ctx.currentTime);
      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 1);
    } catch {
      // Audio not available — fail silently
    }
  }

  function _start() {
    if (_isRunning || _remaining <= 0) return;
    _isRunning = true;
    card.classList.add('is-running');
    card.classList.remove('is-done');
    _intervalId = setInterval(_tick, 1000);
    startBtn.disabled = true;
  }

  function _stop() {
    if (!_isRunning) return;
    _isRunning = false;
    clearInterval(_intervalId);
    _intervalId = null;
    card.classList.remove('is-running');
    elColon.style.opacity = '1';
    startBtn.disabled = false;
    document.title = 'Dashboard';
  }

  function _reset() {
    _stop();
    _remaining = _totalSeconds;
    card.classList.remove('is-done');
    elColon.style.opacity = '1';
    _render();
  }

  /** Apply a custom duration from the input field. */
  function _setDuration() {
    const val = parseInt(durationIn.value, 10);
    if (isNaN(val) || val < 1 || val > 60) {
      durationIn.focus();
      durationIn.select();
      return;
    }
    _stop();
    _totalSeconds = val * 60;
    _remaining    = _totalSeconds;
    card.classList.remove('is-done');
    _render();
  }

  function init() {
    _render();

    startBtn.addEventListener('click', _start);
    stopBtn.addEventListener('click', _stop);
    resetBtn.addEventListener('click', _reset);
    setBtn.addEventListener('click', _setDuration);

    // Allow pressing Enter in the duration input
    durationIn.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') _setDuration();
    });
  }

  return { init };
})();

/* ============================================================
   TODO MODULE
   Handles: add, edit, complete, delete tasks; LocalStorage;
            Challenge 3 (duplicate prevention); sort toggle
   ============================================================ */

const Todo = (() => {
  const form      = document.getElementById('todo-form');
  const input     = document.getElementById('todo-input');
  const errorSpan = document.getElementById('todo-error');
  const listEl    = document.getElementById('todo-list');
  const sortBtn   = document.getElementById('todo-sort');

  // Edit modal elements
  const editOverlay = document.getElementById('edit-modal-overlay');
  const editForm    = document.getElementById('edit-form');
  const editInput   = document.getElementById('edit-input');
  const closeEdit   = document.getElementById('close-edit-modal');

  let _tasks      = [];
  let _sortedMode = false;
  let _editingId  = null;

  const STORAGE_KEY = 'dashboard_tasks';

  /* ── persistence ── */

  function _load() {
    _tasks = Storage.get(STORAGE_KEY, []);
  }

  function _save() {
    Storage.set(STORAGE_KEY, _tasks);
  }

  /* ── helpers ── */

  function _genId() {
    return `t_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
  }

  /** Case-insensitive duplicate check (Challenge 3). */
  function _isDuplicate(text, excludeId = null) {
    const normalised = text.trim().toLowerCase();
    return _tasks.some(
      (t) => t.text.toLowerCase() === normalised && t.id !== excludeId
    );
  }

  /** Return tasks in display order. */
  function _getDisplayTasks() {
    if (!_sortedMode) return [..._tasks];
    return [..._tasks].sort((a, b) =>
      a.text.localeCompare(b.text, undefined, { sensitivity: 'base' })
    );
  }

  /* ── rendering ── */

  function _render() {
    const tasks = _getDisplayTasks();
    listEl.innerHTML = '';

    if (tasks.length === 0) {
      const empty = document.createElement('li');
      empty.className = 'todo__empty';
      empty.textContent = 'No tasks yet. Add one above!';
      listEl.appendChild(empty);
      return;
    }

    tasks.forEach((task) => {
      const li = document.createElement('li');
      li.className = 'todo__item' + (task.done ? ' todo__item--done' : '');
      li.dataset.id = task.id;
      li.setAttribute('role', 'listitem');

      // Checkbox
      const checkbox = document.createElement('input');
      checkbox.type      = 'checkbox';
      checkbox.className = 'todo__checkbox';
      checkbox.checked   = task.done;
      checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.done ? 'incomplete' : 'complete'}`);
      checkbox.addEventListener('change', () => _toggle(task.id));

      // Text
      const span = document.createElement('span');
      span.className   = 'todo__text';
      span.textContent = task.text;

      // Action buttons
      const actions = document.createElement('div');
      actions.className = 'todo__actions';

      const editBtn = document.createElement('button');
      editBtn.className       = 'todo__btn todo__btn--edit';
      editBtn.innerHTML       = '✏️';
      editBtn.setAttribute('aria-label', `Edit task: ${task.text}`);
      editBtn.addEventListener('click', () => _openEdit(task.id));

      const deleteBtn = document.createElement('button');
      deleteBtn.className     = 'todo__btn todo__btn--delete';
      deleteBtn.innerHTML     = '🗑️';
      deleteBtn.setAttribute('aria-label', `Delete task: ${task.text}`);
      deleteBtn.addEventListener('click', () => _delete(task.id));

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      li.appendChild(checkbox);
      li.appendChild(span);
      li.appendChild(actions);
      listEl.appendChild(li);
    });
  }

  /* ── actions ── */

  function _add(text) {
    _tasks.push({ id: _genId(), text: text.trim(), done: false });
    _save();
    _render();
  }

  function _toggle(id) {
    const task = _tasks.find((t) => t.id === id);
    if (task) {
      task.done = !task.done;
      _save();
      _render();
    }
  }

  function _delete(id) {
    _tasks = _tasks.filter((t) => t.id !== id);
    _save();
    _render();
  }

  function _openEdit(id) {
    const task = _tasks.find((t) => t.id === id);
    if (!task) return;
    _editingId        = id;
    editInput.value   = task.text;
    editOverlay.hidden = false;
    editInput.focus();
    editInput.select();
  }

  function _closeEditModal() {
    editOverlay.hidden = true;
    _editingId = null;
  }

  function _saveEdit(e) {
    e.preventDefault();
    const newText = editInput.value.trim();
    if (!newText) return;

    if (_isDuplicate(newText, _editingId)) {
      // Show inline error in modal (reuse edit input border)
      editInput.setCustomValidity('Duplicate task!');
      editInput.reportValidity();
      return;
    }
    editInput.setCustomValidity('');

    const task = _tasks.find((t) => t.id === _editingId);
    if (task) {
      task.text = newText;
      _save();
      _render();
    }
    _closeEditModal();
  }

  /* ── form submission ── */

  function _handleSubmit(e) {
    e.preventDefault();
    errorSpan.textContent = '';

    const text = input.value.trim();

    if (!text) {
      errorSpan.textContent = 'Task cannot be empty.';
      input.focus();
      return;
    }

    // Challenge 3: prevent duplicates
    if (_isDuplicate(text)) {
      errorSpan.textContent = `"${text}" is already in your list.`;
      input.focus();
      return;
    }

    _add(text);
    input.value = '';
    input.focus();
  }

  /* ── sort toggle ── */

  function _toggleSort() {
    _sortedMode = !_sortedMode;
    sortBtn.textContent      = _sortedMode ? '↕ Unsort' : '↕ Sort';
    sortBtn.setAttribute('aria-label',
      _sortedMode ? 'Remove sort' : 'Sort tasks alphabetically'
    );
    _render();
  }

  /* ── modal keyboard / overlay click ── */

  function _editOverlayClick(e) {
    if (e.target === editOverlay) _closeEditModal();
  }

  function _editOverlayKeydown(e) {
    if (e.key === 'Escape') _closeEditModal();
  }

  function init() {
    _load();
    _render();

    form.addEventListener('submit', _handleSubmit);
    sortBtn.addEventListener('click', _toggleSort);

    editForm.addEventListener('submit', _saveEdit);
    closeEdit.addEventListener('click', _closeEditModal);
    editOverlay.addEventListener('click', _editOverlayClick);
    editOverlay.addEventListener('keydown', _editOverlayKeydown);
  }

  return { init };
})();

/* ============================================================
   QUICK LINKS MODULE
   Handles: add link, open in new tab, delete link; LocalStorage
   ============================================================ */

const QuickLinks = (() => {
  const form      = document.getElementById('links-form');
  const nameInput = document.getElementById('links-name');
  const urlInput  = document.getElementById('links-url');
  const errorSpan = document.getElementById('links-error');
  const gridEl    = document.getElementById('links-grid');

  let _links = [];

  const STORAGE_KEY = 'dashboard_links';

  /* ── persistence ── */

  function _load() {
    _links = Storage.get(STORAGE_KEY, []);
  }

  function _save() {
    Storage.set(STORAGE_KEY, _links);
  }

  /* ── helpers ── */

  function _genId() {
    return `l_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
  }

  /** Ensure the URL has a protocol so it doesn't resolve relative to page. */
  function _normaliseUrl(raw) {
    const trimmed = raw.trim();
    if (!/^https?:\/\//i.test(trimmed)) {
      return 'https://' + trimmed;
    }
    return trimmed;
  }

  /* ── rendering ── */

  function _render() {
    gridEl.innerHTML = '';

    if (_links.length === 0) {
      const empty = document.createElement('p');
      empty.className   = 'links__empty';
      empty.textContent = 'No links yet. Add your favourites above!';
      gridEl.appendChild(empty);
      return;
    }

    _links.forEach((link) => {
      const wrapper = document.createElement('div');
      wrapper.className = 'link__item';
      wrapper.setAttribute('role', 'listitem');

      const a = document.createElement('a');
      a.className = 'link__btn';
      a.href      = link.url;
      a.target    = '_blank';
      a.rel       = 'noopener noreferrer';
      a.textContent = link.name;
      a.setAttribute('aria-label', `Open ${link.name}`);

      const delBtn = document.createElement('button');
      delBtn.className = 'link__delete';
      delBtn.innerHTML = '✕';
      delBtn.setAttribute('aria-label', `Remove ${link.name}`);
      delBtn.addEventListener('click', () => _delete(link.id));

      wrapper.appendChild(a);
      wrapper.appendChild(delBtn);
      gridEl.appendChild(wrapper);
    });
  }

  /* ── actions ── */

  function _add(name, url) {
    _links.push({ id: _genId(), name: name.trim(), url });
    _save();
    _render();
  }

  function _delete(id) {
    _links = _links.filter((l) => l.id !== id);
    _save();
    _render();
  }

  /* ── form submission ── */

  function _handleSubmit(e) {
    e.preventDefault();
    errorSpan.textContent = '';

    const name = nameInput.value.trim();
    const raw  = urlInput.value.trim();

    if (!name) {
      errorSpan.textContent = 'Please enter a label for the link.';
      nameInput.focus();
      return;
    }

    if (!raw) {
      errorSpan.textContent = 'Please enter a URL.';
      urlInput.focus();
      return;
    }

    const url = _normaliseUrl(raw);

    // Basic URL sanity check
    try {
      new URL(url);
    } catch {
      errorSpan.textContent = 'Please enter a valid URL (e.g. https://example.com).';
      urlInput.focus();
      return;
    }

    _add(name, url);
    nameInput.value = '';
    urlInput.value  = '';
    nameInput.focus();
  }

  function init() {
    _load();
    _render();
    form.addEventListener('submit', _handleSubmit);
  }

  return { init };
})();

/* ============================================================
   THEME MODULE  (Challenge 1 — Light / Dark mode)
   ============================================================ */

const Theme = (() => {
  const html       = document.documentElement;
  const toggleBtn  = document.getElementById('theme-toggle');
  const icon       = toggleBtn.querySelector('.theme-icon');

  const STORAGE_KEY = 'dashboard_theme';

  function _apply(theme) {
    html.setAttribute('data-theme', theme);
    icon.textContent = theme === 'dark' ? '🌙' : '☀️';
    toggleBtn.setAttribute('aria-label',
      theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'
    );
    Storage.set(STORAGE_KEY, theme);
  }

  function _toggle() {
    const current = html.getAttribute('data-theme');
    _apply(current === 'dark' ? 'light' : 'dark');
  }

  function init() {
    // Respect saved preference; otherwise check system preference
    const saved  = Storage.get(STORAGE_KEY, null);
    const system = window.matchMedia('(prefers-color-scheme: light)').matches
      ? 'light'
      : 'dark';
    _apply(saved ?? system);

    toggleBtn.addEventListener('click', _toggle);
  }

  return { init };
})();

